      "advisory": {
        "tier": "S",
        "role": {
          "en": "Close Quarters One-Shot Stopper",
          "tc": "零距離瞬間爆發制敵",
          "sc": "零距离瞬间爆发制敌"
        },
        "pros": {
          "en": [
            "Full-auto capability delivers overwhelming close-range DPS",
            "Ergonomic weapon profile suited for mobile room-clearing"
          ],
          "tc": [
            "具備全自動模式，近距離交火具備壓倒性 DPS 爆發",
            "優秀的人體工學手感，適合高機動推進走位"
          ],
          "sc": [
            "具备全自动模式，近距离交火具备压倒性 DPS 爆发",
            "优秀的人体工学手感，适合高机动推进走位"
          ]
        },
        "cons": {
          "en": [
            "No Wallbang penetration capability through environmental obstacles",
            "Tactical reloading takes dedication under suppressive fire"
          ],
          "tc": [
            "無穿牆能力，無法對掩體後方目標造成傷害",
            "在敵方持續火力壓制下裝填需尋找良好掩體"
          ],
          "sc": [
            "无穿墙能力，无法对掩体后方目标造成伤害",
            "在敌方持续火力压制下装填需寻找良好掩体"
          ]
        },
        "tips": {
          "en": "Optimal combat range: 0-15m point-blank entry. Recommended attachments: Equip low-magnification reflex optics and recoil compensators for steady sight-picture recovery.",
          "tc": "最佳作戰距離：0-15 公尺室內破門突入。建議配件組合：低倍率內紅點瞄具搭配後座力補償槍口，確保快速連發時瞄準點迅速回正。",
          "sc": "最佳作战距离：0-15 米室内破门突入。建议配件组合：低倍率内红点瞄具搭配后座力补偿枪口，确保快速连发时瞄准点迅速回正。"
        }
      }
