      "intel": [
        {
          "id": "IRL Counterpart",
          "title": {
            "en": "IRL Counterpart",
            "tc": "現實世界原型槍",
            "sc": "现实世界原型枪"
          },
          "dossier": {
            "en": "The Winchester Model 1897 is a pump-action shotgun with its iconic external hammer that protrudes from the rear end of the action for each pump. It is a successor to the model 93, which instead uses the usual hammer similar to that of a revolver.Winchester Model 1897",
            "tc": "The Winchester Model 1897 is a pump-action shotgun with its iconic external hammer that protrudes from the rear end of the action for each pump. It is a successor to the model 93, which instead uses the usual hammer similar to that of a revolver.Winchester Model 1897",
            "sc": "The Winchester Model 1897 is a pump-action shotgun with its iconic external hammer that protrudes from the rear end of the action for each pump. It is a successor to the model 93, which instead uses the usual hammer similar to that of a revolver.Winchester Model 1897"
          }
        },
        {
          "id": "Fun Fact",
          "title": {
            "en": "Fun Fact",
            "tc": "戰地冷知識 / 彩蛋",
            "sc": "战地冷知识 / 彩蛋"
          },
          "dossier": {
            "en": "The Winchester Model 1897 is also known as the \"Riot Gun\" or the \"Trench Gun\". The in-game name \"M79\", however, refers to a completely different weapon in real life: the M79 Grenade Launcher.",
            "tc": "溫徹斯特 M1897 型霰彈槍也被稱為「鎮暴槍」或「壕溝槍」。然而，遊戲中的名稱「M79」在現實生活中指的是一種完全不同的武器：M79 榴彈發射器。",
            "sc": "温彻斯特 M1897 型霰弹枪也被称为「镇暴枪」或「壕沟枪」。然而，游戏中的名称「M79」在现实生活中指的是一种完全不同的武器：M79 榴弹发射器。"
          }
        },
        {
          "id": "More About this Gun",
          "title": {
            "en": "More About this Gun",
            "tc": "外部參考檔案與資料",
            "sc": "外部参考档案与资料"
          },
          "dossier": {
            "en": "External Links: Modern Firearms Wikipedia",
            "tc": "External Links: Modern Firearms Wikipedia",
            "sc": "External Links: Modern Firearms Wikipedia"
          }
        }
      ],
      "advisory": {
        "tier": "A",
        "role": {
          "en": "Close Quarters One-Shot Stopper",
          "tc": "零距離瞬間爆發制敵",
          "sc": "零距离瞬间爆发制敌"
        },
        "pros": {
          "en": [
            "Ergonomic weapon profile suited for mobile room-clearing"
          ],
          "tc": [
            "優秀的人體工學手感，適合高機動推進走位"
          ],
          "sc": [
            "优秀的人体工学手感，适合高机动推进走位"
          ]
        },
        "cons": {
          "en": [
            "Limited magazine capacity (4 RNDs) demands trigger discipline",
            "Semi/Manual action relies strictly on first-shot accuracy",
            "No Wallbang penetration capability through environmental obstacles"
          ],
          "tc": [
            "彈匣容量受限 (4 發)，需嚴格控制開火節奏與裝填時機",
            "單發/手動擊發機制高度考驗第一槍精準度",
            "無穿牆能力，無法對掩體後方目標造成傷害"
          ],
          "sc": [
            "弹匣容量受限 (4 发)，需严格控制开火节奏与装填时机",
            "单发/手动击发机制高度考验第一枪精准度",
            "无穿墙能力，无法对掩体后方目标造成伤害"
          ]
        },
        "tips": {
          "en": "Optimal combat range: 0-15m point-blank entry. Recommended attachments: Equip low-magnification reflex optics and recoil compensators for steady sight-picture recovery.",
          "tc": "最佳作戰距離：0-15 公尺室內破門突入。建議配件組合：低倍率內紅點瞄具搭配後座力補償槍口，確保快速連發時瞄準點迅速回正。",
          "sc": "最佳作战距离：0-15 米室内破门突入。建议配件组合：低倍率内红点瞄具搭配后座力补偿枪口，确保快速连发时瞄准点迅速回正。"
        }
      }
